def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    import statistics

    h = max(0, int(horizon))
    if h == 0:
        return []
    y = []
    for v in history:
        try:
            v = float(v)
            if math.isfinite(v):
                y.append(v)
        except (TypeError, ValueError):
            pass
    if not y:
        return [0.0] * h

    label = str(frequency).lower()
    p = 24 if 'hour' in label else (7 if 'day' in label else 1)
    if len(y) < 2 * p:
        return [float(statistics.median(y[-min(5, len(y)):]))] * h

    def predict(train, steps, alpha, window):
        out = []
        for k in range(steps):
            phase = (len(train) + k) % p
            values = train[phase::p]
            recent = values[-1]
            center = statistics.median(values[-window:])
            out.append(float(alpha * recent + (1.0 - alpha) * center))
        return out

    def smape(actual, predicted):
        terms = []
        for a, b in zip(actual, predicted):
            d = abs(a) + abs(b)
            if d > 1e-12:
                terms.append(200.0 * abs(a - b) / d)
        return sum(terms) / len(terms) if terms else 0.0

    candidates = [(a, w) for w in (3, 4, 5) for a in (0.0, 0.25, 0.5, 0.75, 1.0)]
    origins = list(range(max(3 * p, len(y) - 5 * p), len(y) - p + 1, p))
    scored = []
    for alpha, window in candidates:
        errors = []
        for cut in origins:
            span = min(3 * p, len(y) - cut)
            if span >= p:
                errors.append(smape(y[cut:cut + span], predict(y[:cut], span, alpha, window)))
        if errors:
            weighted = sum((i + 1) * e for i, e in enumerate(errors)) / sum(range(1, len(errors) + 1))
            instability = max(errors) - min(errors)
            scored.append((weighted + 0.20 * instability, abs(alpha - 0.5), alpha, window))

    if scored:
        _, _, alpha, window = min(scored)
    else:
        alpha, window = 0.5, 3
    result = predict(y, h, alpha, window)
    if min(y) >= 0.0:
        result = [max(0.0, v) for v in result]
    return result

def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    import statistics

    h = max(0, int(horizon))
    if h == 0:
        return []
    y = []
    for v in history:
        try:
            v = float(v)
            if math.isfinite(v):
                y.append(v)
        except (TypeError, ValueError):
            pass
    if not y:
        return [0.0] * h

    label = str(frequency).lower()
    p = 24 if 'hour' in label else (7 if 'day' in label else 1)
    if len(y) < p:
        return [float(statistics.median(y))] * h

    nonnegative = min(y) >= 0.0
    out = []
    for k in range(h):
        phase = (len(y) + k) % p
        same_phase = y[phase::p]
        if len(same_phase) >= 3:
            value = statistics.median(same_phase[-3:])
        else:
            value = same_phase[-1]
        if nonnegative:
            value = max(0.0, value)
        out.append(float(value))
    return out
